1	package ociresources
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	
8		tea "charm.land/bubbletea/v2"
9		"github.com/charmbracelet/x/ansi"
10	
11		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
12		"github.com/anthnel/devdesk/internal/ui/testutil"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// DEVDESK-292 step 4c: the launch form refuses an invalid host port of a
17	// ticked EXPOSE port, underlines it after the first refused submit only, and
18	// names it in the footer (Error level, derived on every frame).
19	
20	const curlyUnderline = "4:3"
21	
22	func newValidationForm() *LaunchForm {
23		return NewLaunchForm("api:v1", []string{"80/tcp", "443/tcp"}, nil, 120)
24	}
25	
26	// setHostPort sets the host port of port i and ticks or unticks it.
27	func setHostPort(f *LaunchForm, i int, value string, enabled bool) {
28		f.ports[i].hostPortInput.SetValue(value)
29		f.ports[i].enabled = enabled
30	}
31	
32	// submitLaunch presses enter on the Launch button.
33	func submitLaunch(f *LaunchForm) (*LaunchForm, bool) {
34		focusLaunchField(f, f.fieldSubmit())
35		f, cmd := f.Update(testutil.Key("enter"))
36		if cmd == nil {
37			return f, false
38		}
39		_, ok := testutil.MsgOf[LaunchFormSubmitMsg](cmd)
40		return f, ok
41	}
42	
43	func footerStatus(f *LaunchForm) sharedcomponents.Status {
44		return Model{launchForm: f}.formStatus()
45	}
46	
47	// portLine returns the raw rendered line of the port whose container label is label.
48	func portLine(t *testing.T, f *LaunchForm, label string) string {
49		t.Helper()
50		for _, line := range strings.Split(f.View(), "\n") {
51			if strings.Contains(ansi.Strip(line), ":"+label) && strings.Contains(ansi.Strip(line), "tcp") {
52				return line
53			}
54		}
55		t.Fatalf("no line for port %s in:\n%s", label, ansi.Strip(f.View()))
56		return ""
57	}
58	
59	const portMessage = "Host port for 80/tcp must be a number between 1 and 65535"
60	
61	func REDACTED(t *testing.T) {
62		f := newValidationForm()
63		setHostPort(f, 0, "80a0", true)
64	
65		f, submitted := submitLaunch(f)
66		if submitted {
67			t.Fatal("submit with host port 80a0 on a ticked 80/tcp produced LaunchFormSubmitMsg, want a refusal")
68		}
69		if !strings.Contains(portLine(t, f, "80/tcp"), curlyUnderline) {
70			t.Errorf("port 80/tcp row is not underlined after the refused submit:\n%q", portLine(t, f, "80/tcp"))
71		}
72		if strings.Contains(portLine(t, f, "443/tcp"), curlyUnderline) {
73			t.Error("the valid 443/tcp row is underlined, only the faulty field should be")
74		}
75		st := footerStatus(f)
76		if st.Text != portMessage || st.Level != sharedcomponents.LevelError {
77			t.Errorf("formStatus() = {%q, level %v}, want {%q, LevelError}", st.Text, st.Level, portMessage)
78		}
79	}
80	
81	func TestLaunchFormNothingIsUnderlinedBeforeTheFirstSubmit(t *testing.T) {
82		f := newValidationForm()
83		setHostPort(f, 0, "80a0", true)
84		f.Update(testutil.Key("x")) // a change before any submit must not arm validation
85	
86		if strings.Contains(f.View(), curlyUnderline) {
87			t.Error("an invalid port is underlined before any submit")
88		}
89		if st := footerStatus(f); st.Text != "" {
90			t.Errorf("formStatus().Text = %q before any submit, want empty", st.Text)
91		}
92	}
93	
94	func TestLaunchFormHostPortBounds(t *testing.T) {
95		tests := []struct {
96			value string
97			valid bool
98		}{
99			{"0", false}, {"65536", false}, {"-1", false}, {"80a0", false}, {" 8 0", false},
100			{"1", true}, {"65535", true}, {"8080", true}, {"", true},
101			{"+80", false}, {"٣٣", false}, {"99999999999999999999", false}, {"  ", true}, {" 80 ", true}, {"0080", true}, {"0000", false},
102		}
103		for _, tc := range tests {
104			t.Run("ticked/"+tc.value, func(t *testing.T) {
105				f := newValidationForm()
106				setHostPort(f, 0, tc.value, true)
107				f, submitted := submitLaunch(f)
108				if submitted != tc.valid {
109					t.Errorf("host port %q ticked: submitted = %v, want %v", tc.value, submitted, tc.valid)
110				}
111				if got := strings.Contains(f.View(), curlyUnderline); got == tc.valid {
112					t.Errorf("host port %q ticked: underlined = %v, want %v", tc.value, got, !tc.valid)
113				}
114			})
115			t.Run("unticked/"+tc.value, func(t *testing.T) {
116				f := newValidationForm()
117				setHostPort(f, 0, tc.value, false)
118				f, submitted := submitLaunch(f)
119				if !submitted {
120					t.Errorf("host port %q unticked: refused, an unticked port is never invalid", tc.value)
121				}
122				if strings.Contains(f.View(), curlyUnderline) || footerStatus(f).Text != "" {
123					t.Errorf("host port %q unticked: shows an error", tc.value)
124				}
125			})
126		}
127	}
128	
129	func TestLaunchFormTickingAnInvalidPortRevalidates(t *testing.T) {
130		f := newValidationForm()
131		setHostPort(f, 0, "80a0", true)
132		f, _ = submitLaunch(f)
133	
134		focusLaunchField(f, f.firstPortField())
135		f, _ = f.Update(testutil.Key("space")) // untick
136		if f.ports[0].enabled {
137			t.Fatal("space did not untick the port")
138		}
139		if strings.Contains(f.View(), curlyUnderline) || footerStatus(f).Text != "" {
140			t.Error("unticking the invalid port left the error in place")
141		}
142	}
143	
144	func TestLaunchFormAdditionalPortsAndEnvironmentAreNeverRefused(t *testing.T) {
145		f := newValidationForm()
146		f.extraPortsInput.SetValue("not a port, 99999:abc")
147		f.envInput.SetValue("%%%, =, 1BAD")
148		f, submitted := submitLaunch(f)
149		if !submitted {
150			t.Error("free-form Additional ports / Environment values were refused")
151		}
152		if strings.Contains(f.View(), curlyUnderline) || footerStatus(f).Text != "" {
153			t.Error("Additional ports / Environment are flagged invalid")
154		}
155	}
156	
157	func TestLaunchFormCorrectionClearsTheErrorOnTheNextRender(t *testing.T) {
158		f := newValidationForm()
159		setHostPort(f, 0, "80a0", true)
160		f, _ = submitLaunch(f)
161		if footerStatus(f).Text == "" {
162			t.Fatal("precondition: the refused submit must set a footer error")
163		}
164	
165		focusLaunchField(f, f.firstPortField())
166		f.ports[0].hostPortInput.CursorEnd() // SetValue while blurred leaves the cursor at 0
167		for _, m := range append(testutil.Keys("backspace", "backspace", "backspace", "backspace"), testutil.Type("8080")...) {
168			f, _ = f.Update(m)
169		}
170		if got := f.ports[0].hostPortInput.Value(); got != "8080" {
171			t.Fatalf("host port = %q after correction, want 8080", got)
172		}
173		if strings.Contains(f.View(), curlyUnderline) {
174			t.Error("the port is still underlined after the correction")
175		}
176		if st := footerStatus(f); st.Text != "" {
177			t.Errorf("formStatus().Text = %q after the correction, want empty", st.Text)
178		}
179		if _, ok := submitLaunch(f); !ok {
180			t.Error("submit refused after the correction")
181		}
182	}
183	
184	func TestLaunchFormErrorFollowsAnEditAfterARefusal(t *testing.T) {
185		f := newValidationForm()
186		setHostPort(f, 0, "80", true)
187		setHostPort(f, 1, "", true)
188		f, _ = submitLaunch(f) // accepted: nothing armed yet beyond a clean submit
189		setHostPort(f, 0, "80a0", true)
190		f.ports[0].hostPortInput.SetValue("0")
191		f, submitted := submitLaunch(f)
192		if submitted {
193			t.Fatal("host port 0 was accepted")
194		}
195		// Break the other port: revalidation is live after a refusal.
196		focusLaunchField(f, f.firstPortField()+1)
197		f.ports[1].enabled = true
