1	package components
2	
3	import (
4		"fmt"
5	
6		"charm.land/bubbles/v2/textinput"
7	
8		"github.com/anthnel/devdesk/internal/ui/theme"
9	)
10	
11	// FieldError is one field that failed validation. Key names the field in the
12	// form's own vocabulary; Text is the sentence shown in the footer.
13	type FieldError struct{ Key, Text string }
14	
15	// Validation is what a form's submit found, kept live once a submit was
16	// refused (DEVDESK-292). Nothing is invalid before the first refused submit;
17	// after it every change revalidates the whole form. The zero value is ready
18	// and says nothing.
19	type Validation struct {
20		attempted bool
21		errs      []FieldError
22	}
23	
24	// Submit records the errors a submit found, in display order, and reports
25	// whether the form may proceed. A refused submit arms revalidation; an
26	// accepted one clears every error.
27	func (v *Validation) Submit(errs []FieldError) bool {
28		v.errs = append([]FieldError(nil), errs...)
29		v.attempted = len(errs) > 0
30		return len(errs) == 0
31	}
32	
33	// Revalidate replaces the errors after a change. It does nothing until a
34	// submit has been refused, and stays live afterwards even when the form goes
35	// clean, so a later error shows at once.
36	func (v *Validation) Revalidate(errs []FieldError) {
37		if !v.attempted {
38			return
39		}
40		v.errs = errs
41	}
42	
43	// Invalid reports whether the field named key currently fails validation.
44	func (v Validation) Invalid(key string) bool {
45		for _, e := range v.errs {
46			if e.Key == key {
47				return true
48			}
49		}
50		return false
51	}
52	
53	// Status is the footer line for the current errors: the first one, followed by
54	// "(+N more)" when others remain. It is derived on every call, at LevelError,
55	// so it never expires like a timed FooterMessage. The zero Status means no
56	// error.
57	func (v Validation) Status() Status {
58		if len(v.errs) == 0 {
59			return Status{}
60		}
61		text := v.errs[0].Text
62		if n := len(v.errs) - 1; n > 0 {
63			text = fmt.Sprintf("%s (+%d more)", text, n)
64		}
65		return Status{Text: text, Level: LevelError}
66	}
67	
68	// InvalidMarks remembers which text inputs currently carry the invalid style,
69	// so a form restyles an input only when its state changes. Restyling resets the
70	// input's cursor blink, so doing it on every message (the blink ticks included)
71	// would freeze the cursor. The zero value is ready; every input starts valid.
72	type InvalidMarks struct{ applied map[string]bool }
73	
74	// Sync applies the invalid style to in when invalid differs from what was last
75	// applied under key, and reports whether it did. Call it from Update() only
76	// (Rule 110).
77	func (m *InvalidMarks) Sync(key string, in *textinput.Model, invalid bool) bool {
78		if m.applied[key] == invalid {
79			return false
80		}
81		if m.applied == nil {
82			m.applied = map[string]bool{}
83		}
84		theme.SetTextInputInvalid(in, invalid)
85		m.applied[key] = invalid
86		return true
87	}
